package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A rejection needs a reason; it is kept trimmed. */
public class ValidateReject {
    public void validate(@RequestBody RejectRequest request, Out<RejectRequest> body) throws InvalidClaimException {
        String reason = request == null || request.reason() == null ? "" : request.reason().trim();
        if (reason.isEmpty()) throw new InvalidClaimException("A rejection needs a reason");
        body.set(new RejectRequest(reason));
    }
}
# Reject a PENDING claim with a reason (a steward). A change its status does not allow is a 409,
# a missing reason a 400, and either writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateReject
  govern: [ transaction ]
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.RejectClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: log
# The status it was saved at, with who, when and its due then.
log:
  class: net.officefloor.hq.app.claim.LogClaimStatus
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimRejected
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
        setError('That claim could not be saved (is its reference already used on the sheet?).');
      }
    },
  });

  const move = useMutation({
    mutationFn: ({ id, action }: { id: string; action: Action }) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims/${encodeURIComponent(id)}/${action}`,
        action === 'reject'
          ? { reason: (reasons[id] ?? '').trim() }
          : action === 'void'
            ? { reason: voidReasons[id] ?? '' }
            : action === 'settle'
              ? { on: (settleOn[id] ?? '').trim() }
              : {},
        user,
      ),
    onSuccess: (_c, { id, action }) => {
      if (action === 'reject') setReasons((r) => ({ ...r, [id]: '' }));
      if (action === 'void') setVoidReasons((r) => ({ ...r, [id]: '' }));
      if (action === 'settle') setSettleOn((d) => ({ ...d, [id]: '' }));
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: (_e, { id }) => setRefused({ id, message: 'That status change is not allowed.' }),
  });
    const personId = moveTo[id] ?? '';
    if (personId === '') {
      setRefused({ id, message: 'Pick the person to move the claim to.' });
      return;
    }
    reassign.mutate({ id, personId });
  };

  const act = (id: string, action: Action) => {
    setRefused(null);
    if (action === 'reject' && (reasons[id] ?? '').trim() === '') {
      setRefused({ id, message: 'A rejection needs a reason.' });
      return;
    }
    if (action === 'void' && voidReasonList.length > 0 && !voidReasonList.includes(voidReasons[id] ?? '')) {
      setRefused({ id, message: 'A void needs a reason from the sheet\'s list.' });
      return;
    }
    move.mutate({ id, action });

